// BAD: Generic/misleading names
int d = 30;                 // Distance? Duration?
bool i = false;             // Avoid 'i' for boolean

// GOOD: Descriptive names clarify intent
int total_days_in_month = 30;
double current_velocity = 5.5;

// Boolean Best Practice: Use prefixes (is_, has_, should_)
bool is_data_valid = true;
bool has_pending_changes = false;

// Exception: Standard iteration variables (i, j) in loops
for (int i = 0; i < 5; ++i) {}
